namespace SpriteKind {
    export let PathEnd = SpriteKind.create()
    export let Cursor = SpriteKind.create()
    export let Tower = SpriteKind.create()
    export let ScreenText = SpriteKind.create()
}

// sprite initialization
let towerClone: Sprite = null
let enemySprite: Sprite = null
let cursor: Sprite = null
let target: Sprite = null
let textSprite: TextSprite = null

// game initialization
let gameWave = false
let enemyCount = 0
let enemyNum = 0
let enemyImages: Image[] = []
let gameWaveCount: number = null
let towerVelocity: number = null
let levelNum: number = null
let lives: number = null
let money: number = null

// game functions
function callScene(sceneNum: number) {
    if (sceneNum == 0) {
        // splash screen
        scene.setBackgroundColor(13)
        createTextSprite("Turtles", 8, 9, 10, 80, 20, null)
        createTextSprite("vs. Crabs", 8, 9, 10, 80, 35, null)
        callScene(1)
    } else if (sceneNum == 1) {
        // level select menu
        createTextSprite("Pick a level!", 15, 0, 5, 80, 55, null)
        story.showPlayerChoices("Easy", "Medium", "Hard")
        if (story.checkLastAnswer("Easy")) {
            callScene(2)
        } else if (story.checkLastAnswer("Medium")) {
            callScene(3)
        } else if (story.checkLastAnswer("Hard")) {
            callScene(4)
        }
    } else if (sceneNum == 2) {
        tiles.setCurrentTilemap(assets.tilemap`easyLevel`)
        coverTiles()
        initializeLevel()
        levelNum = 1
    } else if (sceneNum == 3) {
        tiles.setCurrentTilemap(assets.tilemap`medLevel`)
        coverTiles()
        initializeLevel()
        levelNum = 2
    } else if (sceneNum == 4) {
        tiles.setCurrentTilemap(assets.tilemap`hardLevel`)
        coverTiles()
        initializeLevel()
        levelNum = 3
    }
}

scene.onHitWall(SpriteKind.Enemy, function (sprite: Sprite, location: tiles.Location) {
    if (tiles.tileAtLocationEquals(sprite.tilemapLocation(), assets.tile`rightArrow`)) {
        sprite.setVelocity(40, 0)
    } else if (tiles.tileAtLocationEquals(sprite.tilemapLocation(), assets.tile`downArrow`)) {
        sprite.setVelocity(0, 40)
    } else if (tiles.tileAtLocationEquals(sprite.tilemapLocation(), assets.tile`leftRightArrow`)) {
        if (Math.percentChance(50)) {
            sprite.setVelocity(-40, 0)
        } else {
            sprite.setVelocity(40, 0)
        }
    }
})

function coverTiles() {
    tileUtil.createSpritesOnTiles(assets.tile`endTile`, assets.image`pathEndImage`, SpriteKind.PathEnd)
    tileUtil.coverAllTiles(assets.tile`endTile`, assets.tile`sandTileCover`)
    tileUtil.coverAllTiles(assets.tile`rightArrow`, assets.tile`rightPathTile`)
    tileUtil.coverAllTiles(assets.tile`downArrow`, assets.tile`downPathTile`)
    tileUtil.coverAllTiles(assets.tile`leftRightArrow`, assets.tile`pathTile`)
}

function createCursor(image: Image) {
    cursor = sprites.create(image, SpriteKind.Cursor)
    cursor.z = 20
    controller.moveSprite(cursor)
    cursor.setFlag(SpriteFlag.GhostThroughWalls, true)
    cursor.setFlag(SpriteFlag.StayInScreen, true)
}

function initializeLevel() {
    createCursor(assets.image`arrowCursor`)
    gameWaveCount = 0
    lives = 20
    money = 200
    createScreenText()
}

function createTextSprite(text: string, fgColor: number, bgColor: number, fontSize: number, xPos: number, yPos: number, icon: Image) {
    textSprite = textsprite.create(text, bgColor, fgColor)
    textSprite.setMaxFontHeight(fontSize)
    textSprite.setPosition(xPos, yPos)
    textSprite.setIcon(icon)
    textSprite.setKind(SpriteKind.ScreenText)
}

function createScreenText() {
    sprites.destroyAllSpritesOfKind(SpriteKind.ScreenText)
    createTextSprite(convertToText(lives), 1, 11, 8, 121, 4, assets.image`livesIcon`)
    createTextSprite(convertToText(money), 1, 11, 8, 10, 4, assets.image`moneyIcon`)
}

// game wave functions and events
function startWave(waveNum: number) {
    createTextSprite("Wave " + waveNum, 8, 9, 16, 80, 60, null)
    textSprite.lifespan = 1500
    gameWave = true
    enemyCount = 0
    if (waveNum == 1) {
        spawnEnemy(assets.image`redCrabImage`, 4)
    } else if (waveNum == 2) {
        spawnEnemy(assets.image`redCrabImage`, 8)
    } else if (waveNum == 3) {
        spawnEnemy(assets.image`redCrabImage`, 3)
        spawnEnemy(assets.image`blueCrabImage`, 3)
    } else if (waveNum == 4) {
        spawnEnemy(assets.image`redCrabImage`, 5)
        spawnEnemy(assets.image`blueCrabImage`, 5)
    } else if (waveNum == 5) {
        spawnEnemy(assets.image`redCrabImage`, 5)
        spawnEnemy(assets.image`blueCrabImage`, 4)
        spawnEnemy(assets.image`redCrabImage`, 5)
    } else if (waveNum == 6) {
        spawnEnemy(assets.image`redCrabImage`, 4)
        spawnEnemy(assets.image`blueCrabImage`, 4)
        spawnEnemy(assets.image`redCrabImage`, 4)
        spawnEnemy(assets.image`blueCrabImage`, 4)
    } else if (waveNum == 7) {
        spawnEnemy(assets.image`blueCrabImage`, 12)
    } else if (waveNum == 8) {
        spawnEnemy(assets.image`redCrabImage`, 5)
        spawnEnemy(assets.image`greenCrabImage`, 5)
        spawnEnemy(assets.image`redCrabImage`, 5)
    } else if (waveNum == 9) {
        spawnEnemy(assets.image`redCrabImage`, 5)
        spawnEnemy(assets.image`greenCrabImage`, 5)
        spawnEnemy(assets.image`blueCrabImage`, 5)
        spawnEnemy(assets.image`greenCrabImage`, 5)
        spawnEnemy(assets.image`redCrabImage`, 5)
    } else if (waveNum == 10) {
        spawnEnemy(assets.image`redCrabImage`, 5)
        spawnEnemy(assets.image`greenCrabImage`, 5)
        spawnEnemy(assets.image`redCrabImage`, 5)
        spawnEnemy(assets.image`blueCrabImage`, 5)
        spawnEnemy(assets.image`greenCrabImage`, 5)
        spawnEnemy(assets.image`redCrabImage`, 5)
    }
    enemyNum = enemyImages.length
}

function spawnEnemy(image: Image, num: number) {
    for (let count = 0; count < num; count++) {
        enemyImages.unshift(image)
    }
}

game.onUpdateInterval(1000, function () {
    if (gameWave && enemyCount < enemyNum) {
        enemyCount++
        enemySprite = sprites.create(enemyImages.removeAt(enemyImages.length - 1), SpriteKind.Enemy)
        if (levelNum == 1) {
            tiles.placeOnTile(enemySprite, tiles.getTileLocation(0, 3))
        } else if (levelNum == 2) {
            tiles.placeOnTile(enemySprite, tiles.getTileLocation(0, 2))
        } else if (levelNum == 3) {
            tiles.placeOnTile(enemySprite, tiles.getTileLocation(0, 1))
        }
        if (enemySprite.image.equals(assets.image`redCrabImage`)) { // B2
            animation.runImageAnimation(enemySprite, assets.animation`redCrabAnim`, 200, true)
        } else if (enemySprite.image.equals(assets.image`blueCrabImage`)) {
            animation.runImageAnimation(enemySprite, assets.animation`blueCrabAnim`, 200, true)
        } else if (enemySprite.image.equals(assets.image`greenCrabImage`)) {
            animation.runImageAnimation(enemySprite, assets.animation`greenCrabAnim`, 200, true)
        }
        enemySprite.vx = 40
    }
})

scene.onOverlapTile(SpriteKind.Enemy, assets.tile`endTile`, function (sprite: Sprite, location: tiles.Location) {
    if (sprite.image.equals(assets.image`greenCrabImage`)) {
        sprites.destroy(sprite)
        lives -= 3
    } else if (sprite.image.equals(assets.image`blueCrabImage`)) {
        sprites.destroy(sprite)
        lives -= 2
    } else if (sprite.image.equals(assets.image`redCrabImage`)) {
        sprites.destroy(sprite)
        lives -= 1
    }
    createScreenText()
    if (lives <= 0) {
        game.gameOver(false)
    }
})

function endWave() {
    if (gameWaveCount == 10) {
        game.gameOver(true)
    } else {
        gameWave = false
        enemyImages = []
        createCursor(assets.image`arrowCursor`)
        tiles.setTileAt(tiles.getTileLocation(9, 0), assets.tile`playTile`)
        sprites.destroyAllSpritesOfKind(SpriteKind.Projectile)
    }
}

game.onUpdate(function () {
    if (gameWave) {
        if (enemyCount == enemyNum && sprites.allOfKind(SpriteKind.Enemy).length == 0) {
            endWave()
        }
    }
})

// run game
callScene(0)

// gameplay events
controller.A.onEvent(ControllerButtonEvent.Pressed, function () {
    if (cursor.tileKindAt(TileDirection.Center, assets.tile`sandTile`) && money >= 100) {
        money -= 100
        createScreenText()
        towerClone = sprites.create(assets.image`medTowerImage`, SpriteKind.Tower)
        tiles.placeOnTile(towerClone, tiles.getTileLocation(cursor.tilemapLocation().column, cursor.tilemapLocation().row))
        tiles.setTileAt(tiles.getTileLocation(cursor.tilemapLocation().column, cursor.tilemapLocation().row), assets.tile`sandTileCover`)
    }
})

scene.onOverlapTile(SpriteKind.Cursor, assets.tile`playTile`, function (sprite: Sprite, location: tiles.Location) {
    if (controller.A.isPressed()) {
        sprites.destroy(sprite)
        tiles.setTileAt(location, assets.tile`runningTile`)
        gameWaveCount++
        startWave(gameWaveCount)
    }
})

spriteutils.onSpriteKindUpdateInterval(SpriteKind.Tower, 1250, function (sprite: Sprite) {
    if (gameWave) {
        target = spriteutils.getSpritesWithin(SpriteKind.Enemy, 30, sprite)._pickRandom()
        towerVelocity = 40
        if (target) {
            let projectile = sprites.createProjectileFromSprite(assets.image`projectileImage`, sprite, 0, 0)
            spriteutils.setVelocityAtAngle(projectile, spriteutils.angleFrom(sprite, target), towerVelocity)
            projectile.setFlag(SpriteFlag.GhostThroughWalls, true)
        }
    }
})

sprites.onOverlap(SpriteKind.Projectile, SpriteKind.Enemy, function(sprite: Sprite, otherSprite: Sprite) {
    if (otherSprite.image.equals(assets.image`redCrabImage`)) {
        sprites.destroy(sprite)
        sprites.destroy(otherSprite)
        money += 10
    } else if (otherSprite.image.equals(assets.image`blueCrabImage`)) {
        sprites.destroy(sprite)
        otherSprite.setImage(assets.image`redCrabImage`)
        animation.runImageAnimation(otherSprite, assets.animation`redCrabAnim`, 500, true)
        money += 10
    } else if (otherSprite.image.equals(assets.image`greenCrabImage`)) {
        sprites.destroy(sprite)
        otherSprite.setImage(assets.image`blueCrabImage`)
        animation.runImageAnimation(otherSprite, assets.animation`blueCrabAnim`, 500, true)
        money += 10
    }
    createScreenText()
    music.play(music.melodyPlayable(music.pewPew), music.PlaybackMode.UntilDone)
})

